import{_ as e,o as t,c as l,a2 as i}from"./chunks/framework.CFuv5BrO.js";const u=JSON.parse('{"title":"5.1 建立可查看的记忆","description":"记住有用的信息，并说明来源和用途。","frontmatter":{"title":"5.1 建立可查看的记忆","description":"记住有用的信息，并说明来源和用途。","outline":[2,3]},"headers":[],"relativePath":"delivery/stage-5/5-1.md","filePath":"delivery/stage-5/5-1.md","lastUpdated":1794017073000}'),r={name:"delivery/stage-5/5-1.md"};function o(s,a,n,d,c,_){return t(),l("div",null,[...a[0]||(a[0]=[i('<h1 id="_5-1-建立可查看的记忆" tabindex="-1">5.1 建立可查看的记忆 <a class="header-anchor" href="#_5-1-建立可查看的记忆" aria-label="Permalink to &quot;5.1 建立可查看的记忆&quot;">​</a></h1><h2 id="当前状态" tabindex="-1">当前状态 <a class="header-anchor" href="#当前状态" aria-label="Permalink to &quot;当前状态&quot;">​</a></h2><ul><li><strong>已实现：</strong> 记忆先进入候选，确认后才参与召回；记录类型、主题键、范围、标签、来源、置信度、敏感度、有效期和版本；召回记录原因与使用审计，注入上下文带 <code>trusted=&quot;false&quot;</code> 和“不能扩大权限”边界。</li><li><strong>仍未完成：</strong> 自动捕获默认关闭，且只支持从终态任务捕获“经历”记忆；没有从邮件、网页或任意文档自动抽取用户事实。</li></ul><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>让 Hearth 记住对用户真正有用的信息，并能说明每条记忆从哪里来、为什么被使用。用户必须能查看和修改这些记忆。</p><h2 id="怎么做" tabindex="-1">怎么做 <a class="header-anchor" href="#怎么做" aria-label="Permalink to &quot;怎么做&quot;">​</a></h2><ol><li>记录用户事实、项目背景、偏好、承诺和过去任务经验，但只记录有来源的信息。</li><li>每条记忆都标明来源、时间、可信程度、适用范围和敏感程度。</li><li>提供记忆浏览器，用户能看到记住了什么、最近在哪里被使用。</li><li>任务使用记忆时，说明用了哪几条以及为什么相关，避免黑箱召回。</li><li>只把任务需要的最小背景交给执行过程，不把所有记忆一次性塞进去。</li><li>用户修改或删除记忆后，后续任务立即使用新版本。</li></ol>',7)])])}const p=e(r,[["render",o]]);export{u as __pageData,p as default};
